    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A horizontal stroke beginning at the left boundary continues to the right edge.
    # Also continue the row immediately below a stroke when its rightmost colored
    # cell reaches the same endpoint.
    for r, row in enumerate(grid):
        if row[0] == color:
            c = 0
            while c < w and row[c] == color:
                c += 1
            if c < w:
                for j in range(c, w):
                    if row[j] == bg:
                        out[r][j] = 1
                # adjacent row can be the lower, broken portion of the stroke
                if r + 1 < h:
                    lower = grid[r + 1]
                    marks = [j for j, v in enumerate(lower) if v == color]
                    if marks and max(marks) == c - 1:
                        for j in range(c, w):
                            if lower[j] == bg:
                                out[r + 1][j] = 1
    return out
